#!/usr/bin/env bash
# Build the static GitHub Pages preview of the web UI into ./site.
# The demo report is generated by the real pipeline (offline mode), not written by hand.
set -euo pipefail
cd "$(dirname "$0")/.."
rm -rf site
mkdir -p site/static/demo
cp app/web/index.html site/
cp app/web/static/app.css app/web/static/app.js site/static/
MOCK_LLM=true uv run aegispr review --demo --json -o site/static/demo/sample-report.json > /dev/null
cp fixtures/sample_repo/sample_pr.diff site/static/demo/sample.diff
touch site/.nojekyll
echo "Built site/ ($(du -sh site | cut -f1))"
